import { BaseException } from '../../base-exception';
import { Locale } from '../../locale';

export class NetworkOfflineException extends BaseException {
    constructor() {
        super(
            'Network.Offline',
            'Device has lost network connection'
        );
    }

    public localise(locale: Locale) {
        this.buttonText = this.getButtonText(locale);

        switch (locale) {
            case 'it-it':
                this.displayMessage = 'Il tuo dispositivo ha perso la connessione';
                break;
            case 'es-es':
                this.displayMessage = '¡Vaya! Parece que no hay conexión. Comprueba tu internet, reconéctate e inténtalo de nuevo.';
                break;
            default:
                this.displayMessage = 'Oops! We\'ve lost your internet connection. Please reconnect and try again.';
                break;
        }
    }
}
